def solve(inputs: dict) -> float:
    remainders = inputs['remainders']
    moduli = inputs['moduli']

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd_val, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd_val, x, y

    def crt_pair(r1, m1, r2, m2):
        g, p, q = extended_gcd(m1, m2)
        if (r2 - r1) % g != 0:
            return None
        lcm_val = m1 * m2 // g
        x = (r1 + m1 * ((r2 - r1) // g) * p) % lcm_val
        return x, lcm_val

    x, m = remainders[0], moduli[0]
    for i in range(1, len(remainders)):
        result = crt_pair(x, m, remainders[i], moduli[i])
        if result is None:
            return -1
        x, m = result

    return float(x)

